#include "estimate.h"
#include <QStringList>

int parseEstimate(const QString &text)
{
    if (text.trimmed().isEmpty())
        return -1;
    int total = 0;
    const QStringList parts = text.split(' ', Qt::SkipEmptyParts);
    for (const QString &part : parts) {
        const QChar unit = part.back();
        if (part.size() == 1)       // missing number
            return -1;
        const QString numStr = part.left(part.size() - 1);
        int value = 0;
        bool ok = false;
        value = numStr.toInt(&ok);
        if (!ok || value < 0)       // missing / invalid / negative number
            return -1;
        if (unit == 'w')
            total += value * 5 * 8 * 60;
        else if (unit == 'd')
            total += value * 8 * 60;
        else if (unit == 'h')
            total += value * 60;
        else if (unit == 'm')
            total += value;
        else
            return -1;            // unknown unit
    }
    return total;
}

QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return QString();
    if (minutes == 0)
        return "0m";
    QStringList out;
    const int weeks = minutes / (5 * 8 * 60);
    const int days = (minutes % (5 * 8 * 60)) / (8 * 60);
    const int hours = (minutes % (8 * 60)) / 60;
    const int mins = minutes % 60;
    if (weeks)
        out << QString::number(weeks) + "w";
    if (days)
        out << QString::number(days) + "d";
    if (hours)
        out << QString::number(hours) + "h";
    if (mins)
        out << QString::number(mins) + "m";
    return out.join(' ');
}

